"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72215"],{26206(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.ciclo_entre_derivados","status":422,"titulo":"As regras fecham ciclo entre derivados"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.ciclo_entre_derivados","requisitos":["UNI-REQ-0075","UNI-REQ-0077"],"oQueAconteceu":["O administrador substituiu as regras padr\xe3o de um fato derivado por regra (`PUT /api/configuracao/admin/fatos-candidato/{id}/regras-padrao`), e as novas regras citam um fato derivado que, direta ou indiretamente, cita este. Um fato derivado s\xf3 resolve quando todos os fatos que ele cita resolveram, ent\xe3o um ciclo faria cada um esperar pelo outro e nenhum resolveria (UNI-REQ-0075 e UNI-REQ-0077). A mensagem da resposta traz o caminho do ciclo, em c\xf3digos de fato, como `A \u2192 B \u2192 A`.","A confer\xeancia considera as regras padr\xe3o que os outros derivados j\xe1 t\xeam gravadas, com as regras novas no lugar das atuais do fato alterado. Um fato que cita a si mesmo n\xe3o cai aqui: a regra \xe9 recusada por outra confer\xeancia, a da estrutura da deriva\xe7\xe3o.","A recusa vem na lista `errors` da resposta, com `field` igual a `regras`. Nada \xe9 gravado: o fato continua com as regras anteriores."],"comoResolver":["Tire das regras enviadas a condi\xe7\xe3o que cita o derivado que fecha o ciclo, ou ajuste as regras do outro derivado do caminho para que ele deixe de citar este. Depois, envie as regras de novo."],"ondeAparece":["Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);